rest.assertionCode:
def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 400 or not isinstance(responseBody, dict):
        return False
    message = responseBody.get('message')
    code = responseBody.get('code')
    return (isinstance(code, int) and (not isinstance(code, bool))) and code == 40001 and isinstance(message, str) and ('purpose' in message.lower() or '用途' in message)
